from typing import Optional

from .database import Thumbnail, df_thumb, del_thumb as db_del_thumb, thumb as db_thumb
from .db import custom_caption, update_cap, del_caption as db_del_caption, get_caption as db_get_caption


class ThumbnailRepository:
    """Repository interface for thumbnail operations."""

    @staticmethod
    async def save(user_id: int, msg_id: int):
        await df_thumb(user_id, msg_id)

    @staticmethod
    async def delete(user_id: int):
        try:
            await db_del_thumb(user_id)
        except Exception:
            pass

    @staticmethod
    async def get(user_id: int) -> Optional[Thumbnail]:
        return await db_thumb(user_id)


class CaptionRepository:
    """Repository interface for caption operations."""

    @staticmethod
    async def update(user_id: int, caption: str):
        await update_cap(user_id, caption)

    @staticmethod
    async def delete(user_id: int):
        try:
            await db_del_caption(user_id)
        except Exception:
            pass

    @staticmethod
    async def get(user_id: int) -> Optional[custom_caption]:
        return await db_get_caption(user_id)
